447	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
448	                + " key=" + ALERT_THRESHOLD + " value=" + (scaled == null ? "" : scaled.toPlainString()));
449	        return scaled;
450	    }
451	
452	    /** Set the sheet's proof kinds (blank: none), the sheet created first if it was never loaded;
453	     *  not dated. Each is trimmed, blanks and repeats dropped; while any is set, a claim whose due
454	     *  is above the proof threshold needs a proof of each to be settled or approved. Refused (422)
455	     *  when one is neither receipt nor photo. Resolves to the kinds as set, comma separated (null: none). */
456	    @Transactional
457	    public String setProofKinds(String sheetId, String user, String kinds) {
458	        List<String> each = Arrays.stream(kinds.split(",")).map(String::trim).filter(k -> !k.isEmpty())
459	                .distinct().toList();
460	        for (String k : each) {
461	            if (ProofKind.of(k).isEmpty()) {
462	                throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
463	                        "A proof kind is receipt or photo, not " + k);
464	            }
465	        }
466	        String value = each.isEmpty() ? null : String.join(",", each);
467	        Sheet sheet = sheets.load(sheetId, user);
468	        sheets.lock(sheetId);
469	        sheet.setProofKinds(value);
470	        sheets.flush();
471	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
472	                + " key=" + PROOF_KINDS + " value=" + (value == null ? "" : value));
473	        return value;
474	    }
475	
476	    /** Set the sheet's default grade (blank: A), the sheet created first if it was never loaded; not
477	     *  dated. A person the quick-add bar adds, and an import line with a blank grade, is given it;
478	     *  no one already on the sheet changes. Refused (422) when it is not one of the grades. Resolves
479	     *  to the grade as set (null: blank). */
480	    @Transactional
481	    public String setDefaultGrade(String sheetId, String user, String grade) {
482	        String value = grade.trim();
483	        if (!value.isEmpty() && !GRADES.contains(value)) {
484	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
485	                    "The default grade is one of " + String.join(", ", GRADES) + ", not " + value);
486	        }
487	        Sheet sheet = sheets.load(sheetId, user);
488	        sheets.lock(sheetId);
489	        sheet.setDefaultGrade(value.isEmpty() ? null : value);
490	        sheets.flush();
491	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
492	                + " key=" + DEFAULT_GRADE + " value=" + value);
493	        return value.isEmpty() ? null : value;
494	    }
495	
496	    /** The id of the sheet's parent; null when blank (none). */
497	    @Transactional(readOnly = true)
498	    public String parent(String sheetId) {
499	        return sheets.find(sheetId).map(Sheet::getParent).orElse(null);
500	    }
501	
502	    /** Set the sheet's parent (null: none), the sheet created first if it was never loaded; not
503	     *  dated, a grade with no rate of its own in force on a date takes the parent's (then its
504	     *  parent's, up to three levels up), so every live due (and every total) moves with it. Refused
505	     *  (422) when it is the sheet itself, a sheet never loaded, or one with this sheet as an ancestor. */
506	    @Transactional
507	    public String setParent(String sheetId, String user, String parent) {
508	        Sheet sheet = sheets.load(sheetId, user);
509	        sheets.lock(sheetId);
510	        if (parent != null) {
511	            if (parent.equals(sheetId)) {
512	                throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A sheet cannot be its own parent");
513	            }
514	            if (sheets.find(parent).isEmpty()) {
515	                throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "No sheet " + parent + " has been loaded");
516	            }
517	            Set<String> seen = new HashSet<>();
518	            for (String at = parent; at != null && seen.add(at); at = sheets.find(at).map(Sheet::getParent).orElse(null)) {
519	                if (at.equals(sheetId)) {
520	                    throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
521	                            "The sheet " + parent + " has this sheet as an ancestor");
522	                }
523	            }
524	        }
525	        RollupService.Snapshot before = rollup.snapshot(sheetId);
526	        sheet.setParent(parent);
527	        sheets.flush();
528	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
529	                + " key=" + PARENT + " value=" + (parent == null ? "" : parent));
530	        rollup.recordChanges(sheetId, user, before);
531	        return parent;
532	    }
533	
534	    /** The sheet's cap in force on its today; null when there is none. */
535	    @Transactional(readOnly = true)
536	    public BigDecimal cap(String sheetId) {
537	        return sheets.cap(sheetId);
538	    }
539	
540	    /** Set the sheet's cap (null: none) from a date (null: the sheet's today), the sheet created
541	     *  first if it was never loaded; every person's due-total (and so every total) is held to the
542	     *  cap in force on the sheet's today. */
543	    @Transactional
544	    public BigDecimal setCap(String sheetId, String user, BigDecimal cap, LocalDate from) {
545	        Sheet sheet = sheets.load(sheetId, user);
546	        sheets.lock(sheetId);
547	        RollupService.Snapshot before = rollup.snapshot(sheetId);
548	        BigDecimal scaled = cap == null ? null : cap.setScale(2);
549	        record(sheet, user, CAP, scaled == null ? "" : scaled.toPlainString(), from);
550	        rollup.recordChanges(sheetId, user, before);
551	        return scaled;
552	    }
553	
554	    /** The sheet's proof threshold in force on its today; null when there is none. */
555	    @Transactional(readOnly = true)
556	    public BigDecimal proofThreshold(String sheetId) {
557	        return sheets.find(sheetId).map(Sheet::getProofThreshold).orElse(null);
558	    }
559	
560	    /** Set the sheet's proof threshold (null: none) from a date (null: the sheet's today), the
561	     *  sheet created first if it was never loaded; a claim dated from then on to the next from-date
562	     *  whose due is above it cannot be settled or approved while it has no proof. */
563	    @Transactional
564	    public BigDecimal setProofThreshold(String sheetId, String user, BigDecimal threshold, LocalDate from) {
565	        Sheet sheet = sheets.load(sheetId, user);
566	        sheets.lock(sheetId);
567	        BigDecimal scaled = threshold == null ? null : threshold.setScale(2);
568	        record(sheet, user, PROOF_THRESHOLD, scaled == null ? "" : scaled.toPlainString(), from);
569	        return scaled;
570	    }
571	
572	    /** Set a grade's proof threshold (null: none, the grade uses the sheet's) from a date (null:
573	     *  the sheet's today), the sheet created first if it was never loaded; a claim dated from then
574	     *  on to the next from-date whose person's grade then is this one and whose due is above it
575	     *  cannot be settled or approved while it has no proof. */
576	    @Transactional
577	    public BigDecimal setGradeProofThreshold(String sheetId, String user, String grade, BigDecimal threshold, LocalDate from) {
578	        Sheet sheet = sheets.load(sheetId, user);
579	        sheets.lock(sheetId);
580	        BigDecimal scaled = threshold == null ? null : threshold.setScale(2);
581	        record(sheet, user, PROOF_THRESHOLD_OF_GRADE + grade, scaled == null ? "" : scaled.toPlainString(), from);
582	        return scaled;
583	    }
584	
585	    /** Set the sheet's note threshold (null: none) from a date (null: the sheet's today), the
586	     *  sheet created first if it was never loaded; a claim dated from then on to the next from-date
587	     *  whose due is above it cannot be opened while its note is empty. */
588	    @Transactional
589	    public BigDecimal setNoteThreshold(String sheetId, String user, BigDecimal threshold, LocalDate from) {
590	        Sheet sheet = sheets.load(sheetId, user);
591	        sheets.lock(sheetId);
592	        BigDecimal scaled = threshold == null ? null : threshold.setScale(2);
593	        record(sheet, user, NOTE_THRESHOLD, scaled == null ? "" : scaled.toPlainString(), from);
594	        return scaled;
595	    }
596	
597	    /** Set the sheet's review threshold (null: none) from a date (null: the sheet's today), the
598	     *  sheet created first if it was never loaded; a claim dated from then on to the next from-date
599	     *  whose due is above it goes to REVIEW when opened, for a steward to make OPEN. */
600	    @Transactional
601	    public BigDecimal setReviewThreshold(String sheetId, String user, BigDecimal threshold, LocalDate from) {
602	        Sheet sheet = sheets.load(sheetId, user);
603	        sheets.lock(sheetId);
604	        BigDecimal scaled = threshold == null ? null : threshold.setScale(2);
605	        record(sheet, user, REVIEW_THRESHOLD, scaled == null ? "" : scaled.toPlainString(), from);
606	        return scaled;
607	    }
608	
609	    /** Every value recorded for the sheet's dated settings, by key, each key's by from-date. */
610	    @Transactional(readOnly = true)
611	    public Map<String, List<DatedSetting>> datedSettings(String sheetId) {
612	        return sheets.find(sheetId).map(Sheet::getDatedSettings).orElse(Map.of());
613	    }
614	
615	    @Transactional(readOnly = true)
616	    public List<SheetRole> roles(String sheetId) {
617	        return roles.findBySheetIdOrderByUserAsc(sheetId);
618	    }
619	
620	    /** The role a user name acts in on the sheet: a steward while a steward's delegation to it
621	     *  covers the sheet's today, else the role it holds. */
622	    @Transactional(readOnly = true)
623	    public Role roleOf(String sheetId, String user) {
624	        Role held = heldRoleOf(sheetId, user);
625	        return held != Role.STEWARD && delegatorOf(sheetId, user) != null ? Role.STEWARD : held;
626	    }
627	
628	    /** The role a user name holds on the sheet in its own right: a clerk unless set otherwise. */
629	    @Transactional(readOnly = true)
630	    public Role heldRoleOf(String sheetId, String user) {
631	        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
632	    }
633	
634	    /** The steward whose delegation the user name acts under on the sheet's today; null when it
635	     *  acts in its own right (a steward itself, or no delegation covers the sheet's today). */
636	    @Transactional(readOnly = true)
637	    public String delegatorOf(String sheetId, String user) {
638	        List<SheetDelegation> made = delegations.findBySheetIdAndUserOrderByIdDesc(sheetId, user);
639	        if (made.isEmpty() || heldRoleOf(sheetId, user) == Role.STEWARD) {
640	            return null;
641	        }
642	        LocalDate today = sheets.today(sheetId);
643	        return made.stream().filter(d -> d.covers(today)).map(SheetDelegation::getSteward).findFirst().orElse(null);
644	    }
645	
646	    @Transactional(readOnly = true)
647	    public List<SheetDelegation> delegations(String sheetId) {
648	        return delegations.findBySheetIdOrderByIdAsc(sheetId);
649	    }
650	
651	    /** Delegate the steward role to a user name from a date (null: the sheet's today) to a date
652	     *  (null: the from-date), inclusive, the sheet created first if it was never loaded; refused
653	     *  (403) unless the user is a steward in its own right, and (400) for a to-date before the
654	     *  from-date. */
655	    @Transactional
656	    public SheetDelegation delegate(String sheetId, String user, String name, LocalDate from, LocalDate to) {
657	        sheets.load(sheetId, user);
658	        if (heldRoleOf(sheetId, user) != Role.STEWARD) {
659	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may delegate");
660	        }
661	        LocalDate start = from == null ? sheets.today(sheetId) : from;
662	        LocalDate end = to == null ? start : to;
663	        if (end.isBefore(start)) {
664	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date");
665	        }
666	        SheetDelegation made = delegations.saveAndFlush(new SheetDelegation(sheetId, name, user, start, end));
667	        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + user + " user=" + name
668	                + " from=" + start + " to=" + end);
669	        return made;
670	    }
671	
672	    /** The sheet's holidays, earliest first. */
673	    @Transactional(readOnly = true)
674	    public List<LocalDate> holidays(String sheetId) {
675	        return holidays.findBySheetIdOrderByDayAsc(sheetId).stream().map(SheetHoliday::getDay).toList();
676	    }
677	
678	    /** Add a holiday to the sheet, the sheet created first if it was never loaded; refused (409)
679	     *  when the date is on its list already. {@link HolidayAdded} is published once it is on the
680	     *  list, re-fixing the due-by of the claims due on or after it. */
681	    @Transactional
682	    public LocalDate addHoliday(String sheetId, String user, LocalDate day) {
683	        sheets.load(sheetId, user);
684	        sheets.lock(sheetId);
685	        if (holidays.existsBySheetIdAndDay(sheetId, day)) {
686	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The date is a holiday already");
687	        }
688	        holidays.saveAndFlush(new SheetHoliday(sheetId, day));
689	        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user + " date=" + day);
690	        events.publishEvent(new HolidayAdded(sheetId, user, day));
691	        return day;
692	    }
693	
694	    /** The sheet's void reasons, in the order they were added. */
695	    @Transactional(readOnly = true)
696	    public List<String> voidReasons(String sheetId) {
697	        return voidReasons.findBySheetIdOrderByIdAsc(sheetId).stream().map(SheetVoidReason::getReason).toList();
698	    }
699	
700	    /** Whether the reason is on the sheet's list of void reasons. */
701	    @Transactional(readOnly = true)
702	    public boolean isVoidReason(String sheetId, String reason) {
703	        return voidReasons.existsBySheetIdAndReason(sheetId, reason);
704	    }
705	
706	    /** Add a void reason to the sheet, the sheet created first if it was never loaded; refused (409)
707	     *  when the reason is on its list already. */
708	    @Transactional
709	    public String addVoidReason(String sheetId, String user, String reason) {
710	        sheets.load(sheetId, user);
711	        sheets.lock(sheetId);
712	        if (voidReasons.existsBySheetIdAndReason(sheetId, reason)) {
713	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The reason is on the list already");
714	        }
715	        voidReasons.saveAndFlush(new SheetVoidReason(sheetId, reason));
716	        audit.recordOnCommit("VOID_REASON_ADDED sheet=" + sheetId + " by=" + user + " reason=" + reason);
717	        return reason;
718	    }
719	
720	    /** Archive the sheet, the sheet created first if it was never loaded; refused (403) unless the
721	     *  user acts as a steward, and (409) when it is archived already. */
722	    @Transactional
723	    public Sheet archive(String sheetId, String user) {
724	        Sheet sheet = sheets.load(sheetId, user);
725	        sheets.lock(sheetId);
726	        if (roleOf(sheetId, user) != Role.STEWARD) {
727	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may archive the sheet");
728	        }
729	        if (sheet.isArchived()) {
730	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived already");
731	        }
732	        sheet.archive();
733	        sheets.flush();
734	        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + sheetId + " by=" + user);
735	        return sheet;
736	    }
737	
738	    /** Whether the user name is a viewer on the sheet: sees it and may change nothing on it. */
739	    @Transactional(readOnly = true)
740	    public boolean isViewer(String sheetId, String user) {
741	        return roleOf(sheetId, user) == Role.VIEWER;
742	    }
743	
744	    /** Give a user name a role on the sheet, the sheet created first if it was never loaded. */
745	    @Transactional
746	    public SheetRole setRole(String sheetId, String user, String name, Role role) {
747	        sheets.load(sheetId, user);
748	        SheetRole held = roles.findBySheetIdAndUser(sheetId, name).orElse(null);
749	        try {
750	            if (held == null) {
751	                held = roles.saveAndFlush(new SheetRole(sheetId, name, role));
752	            } else {
753	                held.setRole(role);
754	                roles.flush();
755	            }
756	        } catch (DataIntegrityViolationException e) {
757	            // set by another user at the same moment
758	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Role changed at the same moment");
759	        }
760	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role.key());
761	        return held;
762	    }
763	
764	    /** Whether a user may settle a claim showing a due (null: n/a, within any limit) whose person
765	     *  has a grade on the sheet's today: a steward settles anything, a clerk only a due at or below
766	     *  the clerk limit in force (the grade's own when one is set, else the sheet's), if there is one. */
767	    @Transactional(readOnly = true)
768	    public boolean maySettle(String sheetId, String user, String grade, BigDecimal due) {
769	        if (due == null || roleOf(sheetId, user) == Role.STEWARD) {
770	            return true;
771	        }
772	        BigDecimal limit = sheets.find(sheetId).map(s -> s.clerkLimitFor(grade)).orElse(null);
773	        return limit == null || due.compareTo(limit) <= 0;
774	    }
775	
776	    /** The roles the sheet's permission matrix sets for each action, as set; an action left blank
777	     *  (keeping its standing rule) is left out. */
778	    @Transactional(readOnly = true)
779	    public Map<Permission, String> permissions(String sheetId) {
780	        Map<Permission, String> out = new EnumMap<>(Permission.class);
781	        permissions.findBySheetId(sheetId).forEach(p -> out.put(p.getAction(), p.getRoles()));
782	        return out;
783	    }
784	
785	    /** Set the roles that may take an action (blank: its standing rule), comma separated, the
786	     *  sheet created first if it was never loaded; not dated, it applies from now on. */
787	    @Transactional
788	    public String setPermission(String sheetId, String user, Permission action, String rolesText) {
789	        sheets.load(sheetId, user);
790	        sheets.lock(sheetId);
791	        SheetPermission held = permissions.findBySheetIdAndAction(sheetId, action.key()).orElse(null);
792	        if (rolesText.isEmpty()) {
793	            if (held != null) {
794	                permissions.delete(held);
795	            }
796	        } else if (held == null) {
797	            permissions.save(new SheetPermission(sheetId, action, rolesText));
798	        } else {
799	            held.setRoles(rolesText);
800	        }
801	        permissions.flush();
802	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
803	                + " key=" + PERMISSION + action.key() + " value=" + rolesText);
804	        return rolesText;
805	    }
806	
807	    /** Whether the user's role may take the action: as the permission matrix sets it, else by its
808	     *  standing rule; a restricted user takes it as a clerk. */
809	    @Transactional(readOnly = true)
810	    public boolean mayTake(String sheetId, String user, Permission action) {
811	        Role acting = roleOf(sheetId, user);
812	        Role role = acting == Role.RESTRICTED ? Role.CLERK : acting;
813	        return permissions.findBySheetIdAndAction(sheetId, action.key())
814	                .map(p -> p.roleSet().contains(role))
815	                .orElseGet(() -> action.standing().contains(role));
816	    }
817	
818	    /** Refuse (403) the action unless the user's role may take it. */
819	    @Transactional(readOnly = true)
820	    public void refuseUnlessAllowed(String sheetId, String user, Permission action) {
821	        if (!mayTake(sheetId, user, action)) {
822	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
823	                    "The user's role may not " + action.key() + " on this sheet");
824	        }
825	    }
826	}
